"""Real Groq model service provider adapter using the official Groq Python SDK."""

import os
import re
import time
from typing import AsyncIterator, Optional, Dict, Any

from dotenv import load_dotenv

import groq
from groq import AsyncGroq

from app.providers.base import (
    BaseModelProvider,
    ModelProviderError,
    RateLimitError,
    AuthenticationError,
    TimeoutError,
    ProviderServerError,
    ConnectionError,
    InvalidResponseError,
)
from app.providers.schemas import (
    GenerationRequest,
    GenerationResponse,
    StreamChunk,
    TokenUsage,
)

# Regex to sanitize API keys from error messages or logs
API_KEY_REGEX = re.compile(r"gsk_[a-zA-Z0-9]{10,}")


def _sanitize(text: str) -> str:
    """Ensure no API keys are ever leaked in error messages or logs."""
    if not text:
        return ""
    return API_KEY_REGEX.sub("[REDACTED_API_KEY]", str(text))


class GroqProvider(BaseModelProvider):
    """Adapter for Groq Cloud API chat completion models."""

    def __init__(
        self,
        api_key: Optional[str] = None,
        default_model: Optional[str] = None,
        client: Optional[AsyncGroq] = None,
    ):
        """Initialize the Groq provider.

        Args:
            api_key: Optional Groq API key. If omitted, loaded from GROQ_API_KEY env.
            default_model: Optional default model name. If omitted, loaded from GROQ_MODEL env.
            client: Optional pre-configured AsyncGroq client (useful for unit tests / mocking).
        """
        # Load environment variables if not already set
        load_dotenv()

        self._api_key = api_key or os.getenv("GROQ_API_KEY")
        self._default_model = default_model or os.getenv("GROQ_MODEL") or "openai/gpt-oss-120b"

        if client is not None:
            self._client = client
        elif self._api_key:
            self._client = AsyncGroq(api_key=self._api_key)
        else:
            self._client = None

    @property
    def provider_name(self) -> str:
        return "groq"

    @property
    def model_name(self) -> str:
        return self._default_model

    def _ensure_authenticated(self) -> None:
        """Verify that credentials are present before attempting a call."""
        if self._client is None or not self._api_key:
            raise AuthenticationError(
                message="GROQ_API_KEY is not configured in environment or passed to provider.",
                status_code=401,
                provider_name=self.provider_name,
            )

    def _map_groq_error(self, e: Exception) -> ModelProviderError:
        """Translate Groq SDK exceptions into standard ModelProviderError subclasses."""
        if isinstance(e, ModelProviderError):
            return e

        safe_msg = _sanitize(str(e))

        if isinstance(e, groq.RateLimitError):
            retry_after: Optional[float] = None
            if hasattr(e, "response") and e.response is not None:
                try:
                    val = e.response.headers.get("retry-after")
                    if val is not None:
                        retry_after = float(val)
                except Exception:
                    pass
            return RateLimitError(
                message=safe_msg,
                status_code=getattr(e, "status_code", 429) or 429,
                provider_name=self.provider_name,
                details={"type": type(e).__name__},
                retry_after=retry_after,
            )

        if isinstance(e, groq.AuthenticationError):
            return AuthenticationError(
                message=safe_msg,
                status_code=getattr(e, "status_code", 401) or 401,
                provider_name=self.provider_name,
                details={"type": type(e).__name__},
            )

        if isinstance(e, groq.APITimeoutError):
            return TimeoutError(
                message=safe_msg,
                status_code=408,
                provider_name=self.provider_name,
                details={"type": type(e).__name__},
            )

        if isinstance(e, groq.APIConnectionError):
            return ConnectionError(
                message=safe_msg,
                status_code=None,
                provider_name=self.provider_name,
                details={"type": type(e).__name__},
            )

        if isinstance(e, groq.InternalServerError):
            return ProviderServerError(
                message=safe_msg,
                status_code=getattr(e, "status_code", 500) or 500,
                provider_name=self.provider_name,
                details={"type": type(e).__name__},
            )

        if isinstance(e, (groq.BadRequestError, groq.NotFoundError)):
            return InvalidResponseError(
                message=safe_msg,
                status_code=getattr(e, "status_code", 400) or 400,
                provider_name=self.provider_name,
                details={"type": type(e).__name__},
            )

        if isinstance(e, groq.APIStatusError):
            status = getattr(e, "status_code", 500) or 500
            if status == 429:
                return RateLimitError(safe_msg, status_code=status, provider_name=self.provider_name)
            elif status in (401, 403):
                return AuthenticationError(safe_msg, status_code=status, provider_name=self.provider_name)
            elif status >= 500:
                return ProviderServerError(safe_msg, status_code=status, provider_name=self.provider_name)
            else:
                return InvalidResponseError(safe_msg, status_code=status, provider_name=self.provider_name)

        return ProviderServerError(
            message=f"Unexpected error: {safe_msg}",
            status_code=500,
            provider_name=self.provider_name,
            details={"type": type(e).__name__},
        )

    async def generate(self, request: GenerationRequest) -> GenerationResponse:
        """Execute a standard chat completion call."""
        self._ensure_authenticated()

        target_model = request.model or self._default_model
        messages_payload = [{"role": m.role, "content": m.content} for m in request.messages]

        t0 = time.perf_counter()
        try:
            kwargs: Dict[str, Any] = {
                "model": target_model,
                "messages": messages_payload,
            }
            if request.max_tokens is not None:
                kwargs["max_tokens"] = request.max_tokens
            if request.temperature is not None:
                kwargs["temperature"] = request.temperature

            completion = await self._client.chat.completions.create(**kwargs)
            latency = time.perf_counter() - t0

            response_text = ""
            if completion.choices and len(completion.choices) > 0:
                choice = completion.choices[0]
                if choice.message and choice.message.content:
                    response_text = choice.message.content

            usage: Optional[TokenUsage] = None
            if hasattr(completion, "usage") and completion.usage is not None:
                usage = TokenUsage(
                    prompt_tokens=getattr(completion.usage, "prompt_tokens", 0) or 0,
                    completion_tokens=getattr(completion.usage, "completion_tokens", 0) or 0,
                    total_tokens=getattr(completion.usage, "total_tokens", 0) or 0,
                    is_estimated=False,
                )

            return GenerationResponse(
                request_id=request.request_id,
                response_text=response_text,
                provider_name=self.provider_name,
                model_name=target_model,
                time_to_first_token=latency,  # In non-streaming, TTFT is total latency
                total_latency=latency,
                token_usage=usage,
                http_status=200,
            )
        except Exception as e:
            raise self._map_groq_error(e) from e

    async def stream(self, request: GenerationRequest) -> AsyncIterator[StreamChunk]:
        """Stream chunks from Groq API chat completion."""
        self._ensure_authenticated()

        target_model = request.model or self._default_model
        messages_payload = [{"role": m.role, "content": m.content} for m in request.messages]

        t0 = time.perf_counter()
        first_token_time: Optional[float] = None
        chunk_idx = 0

        try:
            kwargs: Dict[str, Any] = {
                "model": target_model,
                "messages": messages_payload,
                "stream": True,
            }
            if request.max_tokens is not None:
                kwargs["max_tokens"] = request.max_tokens
            if request.temperature is not None:
                kwargs["temperature"] = request.temperature

            stream_obj = await self._client.chat.completions.create(**kwargs)

            async for chunk in stream_obj:
                now = time.perf_counter()
                offset = now - t0

                delta_text = ""
                finish_reason = None
                if chunk.choices and len(chunk.choices) > 0:
                    choice = chunk.choices[0]
                    delta = getattr(choice, "delta", None)
                    if delta and getattr(delta, "content", None):
                        delta_text = delta.content
                    finish_reason = getattr(choice, "finish_reason", None)

                if delta_text and first_token_time is None:
                    first_token_time = offset

                # Check if final chunk contains usage
                usage: Optional[TokenUsage] = None
                if hasattr(chunk, "usage") and chunk.usage is not None:
                    usage = TokenUsage(
                        prompt_tokens=getattr(chunk.usage, "prompt_tokens", 0) or 0,
                        completion_tokens=getattr(chunk.usage, "completion_tokens", 0) or 0,
                        total_tokens=getattr(chunk.usage, "total_tokens", 0) or 0,
                        is_estimated=False,
                    )

                is_final = finish_reason is not None

                yield StreamChunk(
                    request_id=request.request_id,
                    chunk_index=chunk_idx,
                    delta_text=delta_text,
                    is_final=is_final,
                    time_offset=offset,
                    token_usage=usage,
                )
                chunk_idx += 1

                if is_final:
                    break

        except Exception as e:
            raise self._map_groq_error(e) from e

"""FastAPI application for the local custom stand-in model simulator."""

from typing import Dict, Any
from fastapi import FastAPI, Request, HTTPException
from fastapi.responses import JSONResponse, StreamingResponse

from app.providers.schemas import GenerationRequest, GenerationResponse
from simulator.config import SimulatorConfig
from simulator.service import SimulatorService

app = FastAPI(
    title="Custom Model Stand-in Simulator",
    description="Deterministic mock model service with configurable latency, rate limits, failures, and concurrency.",
    version="1.0.0",
)

# Global singleton service instance
simulator_service = SimulatorService()


@app.get("/health")
async def health_check() -> Dict[str, Any]:
    """Lightweight health check endpoint."""
    return {"status": "ok", "service": "custom-model-simulator"}


@app.get("/status")
async def status_endpoint() -> Dict[str, Any]:
    """Observability endpoint returning in-flight requests, limits, usage, and metrics."""
    return simulator_service.get_status()


@app.post("/admin/configure")
async def configure_simulator(updates: Dict[str, Any]) -> Dict[str, Any]:
    """Dynamically update simulator behavior (latencies, limits, failure modes)."""
    try:
        new_config = simulator_service.configure(updates)
        return {
            "status": "updated",
            "config": new_config.model_dump(),
        }
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Invalid configuration update: {str(e)}")


@app.post("/admin/reset")
async def reset_simulator() -> Dict[str, Any]:
    """Reset simulator counters and in-flight state."""
    simulator_service.reset()
    return {"status": "reset_successful", "current_state": simulator_service.get_status()}


@app.post(
    "/v1/chat/completions",
    response_model=GenerationResponse,
    responses={
        429: {"description": "Rate limit, budget, or concurrency exceeded"},
        500: {"description": "Simulated server failure"},
    },
)
async def chat_completions(
    gen_request: GenerationRequest,
    raw_request: Request,
):
    """Handle chat completion requests in either standard or streaming mode."""
    if gen_request.stream:
        # Return HTTP Server-Sent Events stream
        return StreamingResponse(
            simulator_service.stream(
                request=gen_request,
                is_disconnected=raw_request.is_disconnected,
            ),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
            },
        )
    else:
        # Standard non-streaming generation
        response = await simulator_service.generate(gen_request)
        return response


