  answer: string;
  status: 'verified' | 'refused' | 'unverified' | string;
  citations: Citation[];
  retrieved_passages: RetrievedDocument[];
  provider: string;
  refusal_reason?: string | null;
  correction_occurred: boolean;
  workflow_metadata: Record<string, unknown>;
}

export type NavigationTab = 'chat' | 'overview' | 'experiments' | 'settings';

export type ConnectionState = 'connected' | 'checking' | 'disconnected' | 'error';

/**
 * Application environment configuration.
 * Reads variables prefixed with VITE_.
 */

export const ENV = {
  // If empty string, uses relative path so Vite proxy forwards to backend
  apiBaseUrl: import.meta.env.VITE_API_BASE_URL || '',
  // Health probe timeout in milliseconds
  requestTimeoutMs: Number(import.meta.env.VITE_REQUEST_TIMEOUT_MS) || 5000,
  // Polling interval for background health checks (ms)
  healthPollIntervalMs: Number(import.meta.env.VITE_POLL_INTERVAL_MS) || 15000,
  // Version and metadata
  appVersion: '1.0.0',
  appName: 'THE RELAY',
};

import { ENV } from '../config/env';
import type { HealthResponse, ReadyResponse } from '../types/api';

export class ApiError extends Error {
  status?: number;
  data?: unknown;

  constructor(message: string, status?: number, data?: unknown) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.data = data;
  }
}

/**
 * Fetch with automatic AbortController timeout.
 */
async function fetchWithTimeout(
  url: string,
  options: RequestInit = {},
  timeoutMs: number = ENV.requestTimeoutMs
): Promise<Response> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });
    return response;
  } catch (error: unknown) {
    if (error instanceof Error && error.name === 'AbortError') {
      throw new ApiError(`Request timed out after ${timeoutMs}ms`, 504);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * API service for interacting with The Relay FastAPI backend.
 */
export const api = {
  /**
   * Check basic service health (/health).
   */
  async getHealth(): Promise<HealthResponse> {
    const url = `${ENV.apiBaseUrl}/health`;
    try {
      const response = await fetchWithTimeout(url, {
        headers: { Accept: 'application/json' },
      });

      if (!response.ok) {
        throw new ApiError(
          `Health check failed with HTTP ${response.status}`,
          response.status
        );
      }

      const data: HealthResponse = await response.json();
      return data;
    } catch (error: unknown) {
      if (error instanceof ApiError) throw error;
      const message = error instanceof Error ? error.message : 'Unknown network error';
      throw new ApiError(`Unable to connect to backend: ${message}`);
    }
  },

  /**
   * Check component readiness (/ready).
   */
  async getReady(): Promise<ReadyResponse> {
    const url = `${ENV.apiBaseUrl}/ready`;
    try {
      const response = await fetchWithTimeout(url, {
        headers: { Accept: 'application/json' },
      });

      if (!response.ok) {
        let errorBody: unknown;
        try {
          errorBody = await response.json();
        } catch {
          // Ignore JSON parse errors on failure responses
        }
        throw new ApiError(
          `Readiness check failed with HTTP ${response.status}`,
          response.status,
          errorBody
        );
      }

      const data: ReadyResponse = await response.json();
      return data;
    } catch (error: unknown) {
      if (error instanceof ApiError) throw error;
      const message = error instanceof Error ? error.message : 'Unknown network error';
      throw new ApiError(`Readiness probe failed: ${message}`);
    }
  },
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { api, ApiError } from '../services/api';
import { ENV } from '../config/env';
import type { HealthResponse, ReadyResponse, ConnectionState } from '../types/api';

export interface BackendHealthState {
  health: HealthResponse | null;
  ready: ReadyResponse | null;
  connectionState: ConnectionState;
  isLoading: boolean;
  error: string | null;
  lastChecked: Date | null;
  latencyMs: number | null;
  refresh: () => Promise<void>;
}

export function useBackendHealth(): BackendHealthState {
  const [health, setHealth] = useState<HealthResponse | null>(null);
  const [ready, setReady] = useState<ReadyResponse | null>(null);
  const [connectionState, setConnectionState] = useState<ConnectionState>('checking');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [lastChecked, setLastChecked] = useState<Date | null>(null);
  const [latencyMs, setLatencyMs] = useState<number | null>(null);

  const isMountedRef = useRef<boolean>(true);

  const checkHealth = useCallback(async () => {
    setIsLoading(true);
    setConnectionState((prev) => (prev === 'connected' ? 'checking' : prev));

    const startTime = performance.now();
    try {
      // Execute health and ready probes in parallel
      const [healthData, readyData] = await Promise.all([
        api.getHealth(),
        api.getReady(),
      ]);

      const elapsed = Math.round(performance.now() - startTime);

      if (!isMountedRef.current) return;

      // Both returned 200 with valid payloads
      setHealth(healthData);
      setReady(readyData);
      setConnectionState('connected');
      setError(null);
      setLatencyMs(elapsed);
      setLastChecked(new Date());
    } catch (err: unknown) {
      if (!isMountedRef.current) return;

      const elapsed = Math.round(performance.now() - startTime);
      setLatencyMs(elapsed);
      setHealth(null);
      setReady(null);
      setConnectionState('disconnected');
      setLastChecked(new Date());

      if (err instanceof ApiError) {
        setError(err.message);
      } else if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('Failed to connect to backend server');
      }
    } finally {
      if (isMountedRef.current) {
        setIsLoading(false);
      }
    }
  }, []);

  useEffect(() => {
    isMountedRef.current = true;
    checkHealth();

    const intervalId = setInterval(() => {
      checkHealth();
    }, ENV.healthPollIntervalMs);

    return () => {
      isMountedRef.current = false;
      clearInterval(intervalId);
    };
  }, [checkHealth]);

  return {
    health,
    ready,
    connectionState,
    isLoading,
    error,
    lastChecked,
    latencyMs,
    refresh: checkHealth,
  };
}

import React from 'react';
