import { StatusDot } from '../ui/StatusDot';
import { Button } from '../ui/Button';
import type { NavigationTab, ConnectionState, ReadyResponse } from '../../types/api';

interface HeaderProps {
  currentTab: NavigationTab;
  onOpenMobileSidebar: () => void;
  connectionState: ConnectionState;
  ready: ReadyResponse | null;
  latencyMs: number | null;
  isLoadingHealth: boolean;
  onRefreshHealth: () => void;
}

const TAB_TITLES: Record<NavigationTab, { title: string; description: string }> = {
  chat: {
    title: 'Research Chat',
    description: 'Evidence-grounded question answering across 3 engineering research papers.',
  },
  overview: {
    title: 'System Overview',
    description: 'Real-time operational status, component readiness, and architecture diagnostics.',
  },
  experiments: {
    title: 'Experiments & Characterization',
    description: 'Controlled load tests, simulator benchmarks, and retrieval quality measurements.',
  },
  settings: {
    title: 'Settings & Configuration',
    description: 'Model provider settings, rate limits, and environment parameters.',
  },
};

export const Header: React.FC<HeaderProps> = ({
  currentTab,
  onOpenMobileSidebar,
  connectionState,
  ready,
  latencyMs,
  isLoadingHealth,
  onRefreshHealth,
}) => {
  const currentMeta = TAB_TITLES[currentTab];

  return (
    <header className="h-16 border-b border-[#20232b] bg-[#0c0d11]/80 backdrop-blur-md sticky top-0 z-30 px-4 lg:px-8 flex items-center justify-between">
      {/* Left: Mobile hamburger & Page Title */}
      <div className="flex items-center gap-3">
        <button
          type="button"
          onClick={onOpenMobileSidebar}
          className="lg:hidden p-2 text-zinc-400 hover:text-zinc-100 hover:bg-zinc-800/80 rounded-lg"
          aria-label="Open sidebar"
        >
          <Menu className="w-5 h-5" />
        </button>

        <div>
          <h1 className="text-base font-semibold text-zinc-100 leading-tight tracking-tight">
            {currentMeta.title}
          </h1>
          <p className="text-xs text-zinc-400 hidden sm:block leading-none mt-0.5">
            {currentMeta.description}
          </p>
        </div>
      </div>

      {/* Right: Live Connection & Actions */}
      <div className="flex items-center gap-3">
        {/* Backend Connectivity Pill */}
        <div
          className={`flex items-center gap-2 px-3 py-1.5 rounded-full border text-xs font-mono transition-colors ${
            connectionState === 'connected'
              ? 'bg-emerald-950/30 border-emerald-800/40 text-emerald-300'
              : connectionState === 'checking'
              ? 'bg-amber-950/30 border-amber-800/40 text-amber-300'
              : 'bg-rose-950/30 border-rose-800/40 text-rose-300'
          }`}
          title={
            connectionState === 'connected'
              ? `Backend active (${ready?.provider || 'FastAPI'}) • Round-trip: ${latencyMs ?? 0}ms`
              : 'Backend disconnected or unreachable'
          }
        >
          <StatusDot state={connectionState} size="sm" />
          <span className="font-medium hidden md:inline">
            {connectionState === 'connected'
              ? 'FastAPI Ready'
              : connectionState === 'checking'
              ? 'Probing API...'
              : 'API Offline'}
          </span>
          {connectionState === 'connected' && latencyMs !== null && (
            <span className="text-[11px] text-emerald-400 hidden xl:inline">
              ({latencyMs}ms)
            </span>
          )}
          {connectionState === 'disconnected' && (
            <AlertCircle className="w-3.5 h-3.5 text-rose-400 hidden sm:inline" />
          )}
        </div>

        {/* Manual Refresh Button */}
        <Button
          variant="secondary"
          size="sm"
          onClick={onRefreshHealth}
          disabled={isLoadingHealth}
          title="Refresh backend status"
          className="h-8 px-2.5"
        >
          <RefreshCw
            className={`w-3.5 h-3.5 text-zinc-400 ${
              isLoadingHealth ? 'animate-spin text-zinc-200' : ''
            }`}
          />
          <span className="hidden sm:inline text-xs ml-1.5">Refresh</span>
        </Button>

        {/* Model Indicator Badge */}
        {ready?.model && (
          <div className="hidden lg:flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-zinc-800/60 border border-zinc-700/60 text-[11px] font-mono text-zinc-300">
            <Server className="w-3.5 h-3.5 text-zinc-400" />
            <span className="max-w-[140px] truncate" title={ready.model}>
              {ready.model}
            </span>
          </div>
        )}
      </div>
    </header>
  );
};

