/**
 * Application environment configuration.
 * Reads variables prefixed with VITE_.
 */

export const ENV = {
  // If empty string, uses relative path so Vite proxy forwards to backend
  apiBaseUrl: import.meta.env.VITE_API_BASE_URL || '',
  // Health probe timeout in milliseconds
  requestTimeoutMs: Number(import.meta.env.VITE_REQUEST_TIMEOUT_MS) || 5000,
  // Inference question answering timeout in milliseconds (default 60s)
  askTimeoutMs: Number(import.meta.env.VITE_ASK_TIMEOUT_MS) || 60000,
  // Polling interval for background health checks (ms)
  healthPollIntervalMs: Number(import.meta.env.VITE_POLL_INTERVAL_MS) || 15000,
  // Version and metadata
  appVersion: '1.0.0',
  appName: 'THE RELAY',
};

/**
 * TypeScript interfaces matching the exact FastAPI backend schemas.
 * Inspected from:
 * - app/api/schemas.py
 * - app/api/routes.py
 * - app/workflow/schemas.py
 */

export interface HealthResponse {
  status: string; // e.g. "ok"
  service: string; // e.g. "relay-research-assistant"
}

export interface ReadyComponents {
  retriever?: string; // "initialized" | "uninitialized"
  traffic_manager?: string; // "initialized" | "uninitialized"
  workflow?: string; // "initialized" | "uninitialized"
  [key: string]: string | undefined;
}

export interface ReadyResponse {
  status: string; // e.g. "ready"
  provider: string; // e.g. "simulator" | "groq"
  model: string; // e.g. "openai/gpt-oss-120b"
  components: ReadyComponents;
}

export interface ReadyErrorDetail {
  status: string; // "not_ready"
  components: ReadyComponents;
}

