                <div className="mt-2 p-3 rounded-lg bg-[#090a0d] border border-[#1b1e25] text-xs font-mono text-zinc-400 overflow-x-auto max-h-48">
                  <pre>{JSON.stringify(response.workflow_metadata, null, 2)}</pre>
                </div>
              )}
            </div>
          )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import {
  User,
  Sparkles,
  AlertCircle,
  RefreshCw,
  Loader2,
  FileText,
} from 'lucide-react';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import { AnswerCard } from './AnswerCard';
import type { ChatMessage } from '../../types/api';

interface ChatMessageItemProps {
  message: ChatMessage;
  onRetry: (message: ChatMessage) => void;
}

export const ChatMessageItem: React.FC<ChatMessageItemProps> = ({
  message,
  onRetry,
}) => {
  const [elapsedSec, setElapsedSec] = useState<number>(0);

  useEffect(() => {
    if (message.status !== 'loading') return;
    const interval = setInterval(() => {
      setElapsedSec((prev) => prev + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, [message.status]);

  const paperNames: Record<string, string> = {
    '1706.03762v7': 'Attention (1706.03762v7)',
    '2410.00037v1': 'Moshi (2410.00037v1)',
    '2507.07955v2': 'Dynamic Chunking (2507.07955v2)',
  };

  return (
    <div className="space-y-4 py-2">
      {/* 1. User Question Row */}
      <div className="flex items-start gap-3 justify-end">
        <div className="max-w-2xl w-full space-y-1 text-right">
          <div className="flex items-center justify-end gap-2 text-xs font-mono text-zinc-400">
            {message.paperFilter ? (
              <Badge variant="blue" size="sm" icon={<FileText className="w-3 h-3" />}>
                Filter: {paperNames[message.paperFilter] || message.paperFilter}
              </Badge>
            ) : (
              <Badge variant="neutral" size="sm">
                Corpus: All 3 Papers
              </Badge>
            )}
            <span>{message.submittedAt.toLocaleTimeString()}</span>
          </div>

          <div className="inline-block p-4 rounded-xl bg-[#1c2029] border border-[#2b313e] text-zinc-100 text-sm text-left shadow-xs whitespace-pre-wrap selection:bg-zinc-700">
            {message.question}
          </div>
        </div>

        <div className="w-8 h-8 rounded-lg bg-zinc-800 border border-zinc-700 flex items-center justify-center text-zinc-300 shrink-0 mt-6">
          <User className="w-4 h-4" />
        </div>
      </div>

      {/* 2. Assistant Response Row */}
      <div className="flex items-start gap-3">
        <div className="w-8 h-8 rounded-lg bg-zinc-900 border border-zinc-700/80 flex items-center justify-center text-emerald-400 shrink-0 mt-1 shadow-xs">
          <Sparkles className="w-4 h-4" />
        </div>

        <div className="flex-1 max-w-4xl space-y-2">
          {/* Loading State: Honest Non-Streaming Processing Indicator */}
          {message.status === 'loading' && (
            <div className="p-5 rounded-xl bg-[#101216] border border-[#21242d] space-y-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2.5">
                  <Loader2 className="w-4 h-4 animate-spin text-emerald-400" />
                  <span className="text-xs font-semibold text-zinc-200 font-mono">
                    Research Assistant Processing...
                  </span>
                </div>
                <span className="text-xs font-mono text-zinc-400">
                  {elapsedSec}s elapsed
                </span>
              </div>

              <div className="text-xs text-zinc-400 space-y-1.5 leading-relaxed font-mono">
                <p>
                  • Executing hybrid retrieval across ChromaDB (dense), Rank-BM25 (sparse), and SQLite FactStore.
                </p>
                <p>
                  • Evaluating evidence sufficiency and generating verified bracketed citations.
                </p>
              </div>

              <div className="w-full bg-[#181a20] h-1.5 rounded-full overflow-hidden">
                <div className="bg-emerald-500 h-full w-2/5 animate-pulse rounded-full" />
              </div>
            </div>
          )}

          {/* Error State */}
          {message.status === 'error' && (
            <div className="p-4 rounded-xl bg-rose-950/20 border border-rose-900/50 space-y-3 text-xs">
              <div className="flex items-center gap-2 font-semibold text-rose-300 font-mono">
                <AlertCircle className="w-4 h-4 text-rose-400 shrink-0" />
                <span>Request Execution Failed</span>
              </div>

              <p className="text-rose-200/90 leading-relaxed font-mono pl-6">
                {message.error || 'An unexpected failure occurred while processing this query.'}
              </p>

              <div className="pl-6 pt-1">
                <Button
                  variant="danger"
                  size="sm"
                  onClick={() => onRetry(message)}
                  leftIcon={<RefreshCw className="w-3.5 h-3.5" />}
                >
                  Retry Question
                </Button>
              </div>
            </div>
          )}

          {/* Success State */}
          {message.status === 'success' && message.response && (
            <AnswerCard
              response={message.response}
              durationMs={message.durationMs}
            />
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useEffect } from 'react';
import { Send, Loader2, AlertCircle, FileText } from 'lucide-react';
import { Button } from '../ui/Button';
import type { ConnectionState } from '../../types/api';

interface QuestionComposerProps {
  input: string;
  onChangeInput: (val: string) => void;
  selectedFilter: string;
  onSelectFilter: (filter: string) => void;
  onSubmit: () => void;
  isSubmitting: boolean;
  connectionState: ConnectionState;
}

const PAPER_OPTIONS = [
  { id: 'all', label: 'All 3 Papers', paperId: null },
  { id: '1706.03762v7', label: '1706.03762v7 (Attention)', paperId: '1706.03762v7' },
  { id: '2410.00037v1', label: '2410.00037v1 (Moshi)', paperId: '2410.00037v1' },
  { id: '2507.07955v2', label: '2507.07955v2 (Chunking)', paperId: '2507.07955v2' },
];

export const QuestionComposer: React.FC<QuestionComposerProps> = ({
  input,
  onChangeInput,
  selectedFilter,
  onSelectFilter,
  onSubmit,
  isSubmitting,
  connectionState,
}) => {
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Auto-focus on mount
  useEffect(() => {
    textareaRef.current?.focus();
  }, []);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      if (input.trim() && !isSubmitting) {
        onSubmit();
      }
    }
  };

  const isInputEmpty = !input.trim();
  const isBackendOffline = connectionState === 'disconnected';

  return (
    <div className="rounded-xl bg-[#111318] border border-[#262a33] shadow-md p-3 sm:p-4 space-y-3 transition-colors">
      {/* Paper Filter Pills */}
      <div className="flex items-center gap-1.5 overflow-x-auto pb-1 text-xs">
        <span className="text-zinc-400 font-mono text-[11px] mr-1 shrink-0 flex items-center gap-1">
          <FileText className="w-3 h-3 text-zinc-400" />
          Filter:
        </span>
        {PAPER_OPTIONS.map((opt) => {
          const isActive = selectedFilter === opt.id;
          return (
            <button
              key={opt.id}
              type="button"
              onClick={() => onSelectFilter(opt.id)}
              disabled={isSubmitting}
              className={`px-2.5 py-1 rounded-md text-xs font-mono transition-colors shrink-0 cursor-pointer disabled:opacity-50 ${
                isActive
                  ? 'bg-zinc-700 text-white font-medium shadow-xs'
                  : 'bg-zinc-800/80 text-zinc-400 hover:text-zinc-200'
              }`}
            >
              {opt.label}
            </button>
          );
        })}
      </div>

      {/* Controlled Textarea */}
      <div className="relative">
        <textarea
          ref={textareaRef}
          rows={3}
          value={input}
          onChange={(e) => onChangeInput(e.target.value)}
          onKeyDown={handleKeyDown}
          disabled={isSubmitting}
          placeholder="Ask a research question regarding attention formulas, neural codec frames, or chunking evaluations... (Enter to send, Shift+Enter for newline)"
          className="w-full bg-[#0d0e12] border border-[#272b34] rounded-lg p-3 text-sm text-zinc-100 placeholder:text-zinc-500 focus:outline-none focus:border-zinc-500 resize-none font-sans disabled:opacity-60"
        />
      </div>

      {/* Footer Actions & Status */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 pt-1">
        {/* Offline Warning or Hint */}
        <div className="flex items-center gap-2 text-xs font-mono">
          {isBackendOffline ? (
            <div className="flex items-center gap-1.5 text-rose-400">
              <AlertCircle className="w-3.5 h-3.5 shrink-0" />
              <span>Backend API is currently offline. Start server to query.</span>
            </div>
          ) : (
            <span className="text-zinc-400 text-[11px]">
              Answers strictly grounded in 3 arXiv PDFs with verified citations
            </span>
          )}
        </div>

        {/* Submit Button */}
        <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
          <Button
            variant="primary"
            size="md"
            onClick={onSubmit}
            disabled={isInputEmpty || isSubmitting || isBackendOffline}
            isLoading={isSubmitting}
            rightIcon={!isSubmitting ? <Send className="w-3.5 h-3.5" /> : undefined}
            className="w-full sm:w-auto min-w-[130px]"
          >
            {isSubmitting ? 'Consulting...' : 'Ask Question'}
          </Button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
