16: /**
17:  * Fetch helper with automatic AbortController timeout and optional external signal.
18:  */
19: async function fetchWithTimeout(
20:   url: string,
21:   options: RequestInit = {},
22:   timeoutMs: number = ENV.requestTimeoutMs,
23:   externalSignal?: AbortSignal
24: ): Promise<Response> {
25:   const controller = new AbortController();
26:   const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
27: 
28:   // Link external signal if provided
29:   const onExternalAbort = () => controller.abort();
30:   if (externalSignal) {
31:     if (externalSignal.aborted) {
32:       clearTimeout(timeoutId);
33:       controller.abort();
34:     } else {
35:       externalSignal.addEventListener('abort', onExternalAbort, { once: true });
36:     }
37:   }
38: 
39:   try {
40:     const response = await fetch(url, {
41:       ...options,
42:       signal: controller.signal,
43:     });
44:     return response;
45:   } catch (error: unknown) {
46:     if (error instanceof Error && error.name === 'AbortError') {
47:       if (externalSignal?.aborted) {
48:         throw new ApiError('Request was canceled by user', 499);
49:       }
50:       throw new ApiError(`Request timed out after ${Math.round(timeoutMs / 1000)}s`, 504);
51:     }
52:     throw error;
53:   } finally {
54:     clearTimeout(timeoutId);
55:     if (externalSignal) {
56:       externalSignal.removeEventListener('abort', onExternalAbort);
57:     }
58:   }
59: }
