61: /**
62:  * Extract human-readable error detail from a FastAPI error response.
63:  */
64: function extractErrorDetail(errorData: unknown, fallbackStatus: number): string {
65:   if (typeof errorData === 'object' && errorData !== null) {
66:     const errObj = errorData as Record<string, unknown>;
67:     if (typeof errObj.detail === 'string') {
68:       return errObj.detail;
69:     }
70:     if (Array.isArray(errObj.detail)) {
71:       // Pydantic validation error array
72:       const first = errObj.detail[0];
73:       if (first && typeof first === 'object' && 'msg' in first) {
74:         return String(first.msg);
75:       }
76:     }
77:     if (errObj.detail && typeof errObj.detail === 'object') {
78:       return JSON.stringify(errObj.detail);
79:     }
80:   }
81:   return `HTTP ${fallbackStatus} request failed`;
82: }
