100:           `Health check failed with HTTP ${response.status}`,
101:           response.status
102:         );
103:       }
104: 
105:       const data: HealthResponse = await response.json();
106:       return data;
107:     } catch (error: unknown) {
108:       if (error instanceof ApiError) throw error;
109:       const message = error instanceof Error ? error.message : 'Unknown network error';
110:       throw new ApiError(`Unable to connect to backend: ${message}`);
111:     }
112:   },
113: 
114:   /**
115:    * Check component readiness (/ready).
116:    */
117:   async getReady(): Promise<ReadyResponse> {
118:     const url = `${ENV.apiBaseUrl}/ready`;
119:     try {
120:       const response = await fetchWithTimeout(url, {
121:         headers: { Accept: 'application/json' },
122:       });
123: 
124:       if (!response.ok) {
125:         let errorBody: unknown;
126:         try {
127:           errorBody = await response.json();
128:         } catch {
129:           // Ignore JSON parse errors on failure responses
130:         }
131:         throw new ApiError(
132:           `Readiness check failed with HTTP ${response.status}`,
133:           response.status,
134:           errorBody
135:         );
136:       }
137: 
138:       const data: ReadyResponse = await response.json();
139:       return data;
140:     } catch (error: unknown) {
141:       if (error instanceof ApiError) throw error;
142:       const message = error instanceof Error ? error.message : 'Unknown network error';
143:       throw new ApiError(`Readiness probe failed: ${message}`);
144:     }
145:   },
146: 
147:   /**
148:    * Submit research question to /v1/ask.
149:    */
150:   async askQuestion(
151:     req: AskRequest,
152:     externalSignal?: AbortSignal
153:   ): Promise<AskResponse> {
154:     const url = `${ENV.apiBaseUrl}/v1/ask`;
155: 
156:     const body: Record<string, unknown> = {
157:       question: req.question.trim(),
158:     };
159:     if (req.paper_filter) {
160:       body.paper_filter = req.paper_filter.trim();
161:     }
162: 
163:     try {
164:       const response = await fetchWithTimeout(
165:         url,
166:         {
167:           method: 'POST',
168:           headers: {
169:             'Content-Type': 'application/json',
170:             Accept: 'application/json',
171:           },
172:           body: JSON.stringify(body),
173:         },
174:         ENV.askTimeoutMs,
175:         externalSignal
176:       );
177: 
178:       if (!response.ok) {
179:         let errorData: unknown;
180:         try {
181:           errorData = await response.json();
182:         } catch {
183:           // Non-JSON error response
184:         }
185: 
186:         const detailMsg = extractErrorDetail(errorData, response.status);
187: 
188:         if (response.status === 400) {
189:           throw new ApiError(`Invalid request: ${detailMsg}`, 400, errorData);
190:         } else if (response.status === 422) {
191:           throw new ApiError(`Validation error: ${detailMsg}`, 422, errorData);
192:         } else if (response.status === 429) {
193:           throw new ApiError(`Rate limit reached: ${detailMsg}`, 429, errorData);
194:         } else if (response.status === 502) {
195:           throw new ApiError(`Upstream model provider error: ${detailMsg}`, 502, errorData);
196:         } else if (response.status === 503) {
197:           throw new ApiError(`Service unavailable: ${detailMsg}`, 503, errorData);
198:         } else if (response.status === 504) {
199:           throw new ApiError(`Processing timeout: ${detailMsg}`, 504, errorData);
200:         } else {
201:           throw new ApiError(`Server error (${response.status}): ${detailMsg}`, response.status, errorData);
202:         }
203:       }
204: 
205:       const data: AskResponse = await response.json();
206:       return data;
207:     } catch (error: unknown) {
208:       if (error instanceof ApiError) throw error;
209:       const message = error instanceof Error ? error.message : 'Unknown network error';
210:       throw new ApiError(`Connection failed: ${message}`);
211:     }
212:   },
213: };

