import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Activity,
  CheckCircle2,
  XCircle,
  Server,
  Layers,
  ShieldCheck,
  RefreshCw,
  Database,
  Clock,
  Cpu,
  AlertTriangle,
  AlertCircle,
  BarChart2,
  Radio,
  Zap,
  Gauge,
} from 'lucide-react';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { Button } from '../components/ui/Button';
import { StatusDot } from '../components/ui/StatusDot';
import { api } from '../services/api';
import type {
  HealthResponse,
  ReadyResponse,
  ConnectionState,
  MetricsResponse,
} from '../types/api';

interface OverviewPageProps {
  health: HealthResponse | null;
  ready: ReadyResponse | null;
  connectionState: ConnectionState;
  isLoading: boolean;
  error: string | null;
  lastChecked: Date | null;
  latencyMs: number | null;
  onRefresh: () => void;
}

export const OverviewPage: React.FC<OverviewPageProps> = ({
  health,
  ready,
  connectionState,
  isLoading,
  error,
  lastChecked,
  latencyMs,
  onRefresh,
}) => {
  const isOnline = connectionState === 'connected';

  // Live Metrics state
  const [metrics, setMetrics] = useState<MetricsResponse | null>(null);
  const [isMetricsLoading, setIsMetricsLoading] = useState<boolean>(false);
  const [lastMetricsUpdate, setLastMetricsUpdate] = useState<Date | null>(null);
  const [isStale, setIsStale] = useState<boolean>(false);
  const [secondsAgo, setSecondsAgo] = useState<number>(0);

  const abortControllerRef = useRef<AbortController | null>(null);
  const isFetchingRef = useRef<boolean>(false);

  // Fetch metrics function
  const fetchMetrics = useCallback(async () => {
    if (isFetchingRef.current) return;
    isFetchingRef.current = true;
    setIsMetricsLoading(true);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      const data = await api.getMetrics(controller.signal);
      setMetrics(data);
      setLastMetricsUpdate(new Date());
      setIsStale(false);
      setSecondsAgo(0);
    } catch {
      // Preserve existing metrics snapshot if available; mark as stale
      if (metrics) {
        setIsStale(true);
      }
    } finally {
      setIsMetricsLoading(false);
      isFetchingRef.current = false;
      abortControllerRef.current = null;
    }
  }, [metrics]);

  // Periodic polling every 5,000ms
  useEffect(() => {
    fetchMetrics();
    const interval = setInterval(() => {
      fetchMetrics();
    }, 5000);

    return () => {
      clearInterval(interval);
      if (abortControllerRef.current) {
        abortControllerRef.current.abort();
      }
    };
