import React, { useState, useEffect, useCallback } from 'react';
import {
  TrendingUp,
  BarChart3,
  Database,
  RefreshCw,
  FileSpreadsheet,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Zap,
  Clock,
  Layers,
  Info,
  DollarSign,
  Filter,
  Check,
  Percent,
} from 'lucide-react';
import { Card } from '../components/ui/Card';
import { Badge } from '../components/ui/Badge';
import { Button } from '../components/ui/Button';
import { api, ApiError } from '../services/api';
import type {
  ExperimentsOverviewResponse,
  LoadExperimentsResponse,
  RetrievalExperimentsResponse,
  LoadScenarioStats,
} from '../types/api';

type TabType = 'traffic' | 'retrieval' | 'catalog';
type SourceFilter = 'all' | 'real' | 'simulator';
type RetrievalView = 'comparison' | 'stage8b2' | 'stage6' | 'top_k';

export const ExperimentsPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<TabType>('traffic');
  const [overview, setOverview] = useState<ExperimentsOverviewResponse | null>(null);
  const [loadData, setLoadData] = useState<LoadExperimentsResponse | null>(null);
  const [retrievalData, setRetrievalData] = useState<RetrievalExperimentsResponse | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [lastFetched, setLastFetched] = useState<Date | null>(null);

  // Traffic filters
  const [sourceFilter, setSourceFilter] = useState<SourceFilter>('all');
  const [selectedScenarioId, setSelectedScenarioId] = useState<string>('all');

  // Retrieval filters
  const [retrievalView, setRetrievalView] = useState<RetrievalView>('comparison');
  const [kFilter, setKFilter] = useState<'all' | '5' | '8' | '10'>('all');

  const fetchExperimentData = useCallback(async (isManualRefresh: boolean = false) => {
    if (isManualRefresh) {
      setIsRefreshing(true);
    } else {
      setIsLoading(true);
    }
    setError(null);

    try {
      const [overviewRes, loadRes, retrievalRes] = await Promise.all([
        api.getExperimentsOverview(),
        api.getLoadExperiments(),
        api.getRetrievalExperiments(),
      ]);

      setOverview(overviewRes);
      setLoadData(loadRes);
      setRetrievalData(retrievalRes);
      setLastFetched(new Date());
    } catch (err: unknown) {
      if (err instanceof ApiError) {
        setError(err.message);
      } else {
        setError(err instanceof Error ? err.message : 'Failed to fetch experiment data');
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchExperimentData();
  }, [fetchExperimentData]);

  // Filter load scenarios
  const filteredScenarios: LoadScenarioStats[] = (loadData?.scenarios || []).filter((sc) => {
    if (sourceFilter !== 'all' && sc.source !== sourceFilter) return false;
    if (selectedScenarioId !== 'all' && sc.scenario_id !== selectedScenarioId) return false;
    return true;
  });

  return (
    <div className="space-y-6 max-w-6xl mx-auto pb-12">
      {/* Header Banner */}
      <div className="p-5 rounded-xl bg-gradient-to-r from-[#12151b] via-[#101318] to-[#0c0e12] border border-[#22262f] flex flex-col md:flex-row items-start md:items-center justify-between gap-4 shadow-sm">
        <div className="space-y-1">
          <div className="flex flex-wrap items-center gap-2">
            <h2 className="text-lg font-bold text-zinc-100 flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-sky-400" />
              <span>Experiment Analytics & Empirical Frontiers</span>
            </h2>
            <Badge variant="blue" size="sm">
              Empirical Measurements
            </Badge>
            <Badge variant="neutral" size="sm">
              Read-Only
            </Badge>
          </div>
          <p className="text-xs text-zinc-400 max-w-2xl leading-relaxed">
            Interactive characterization dashboard analyzing traffic dynamics across 5 load scenarios, real Groq baseline vs simulator fidelity, and retrieval quality vs cost trade-offs.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-2 self-stretch md:self-auto justify-between md:justify-end">
          {lastFetched && (
            <span className="text-[11px] font-mono text-zinc-400">
              Fetched {lastFetched.toLocaleTimeString()}
            </span>
          )}
          <Button
            variant="secondary"
            size="sm"
            onClick={() => fetchExperimentData(true)}
            isLoading={isRefreshing}
            leftIcon={<RefreshCw className={`w-3.5 h-3.5 ${isRefreshing ? 'animate-spin' : ''}`} />}
          >
            Refresh
          </Button>
        </div>
      </div>

      {/* Error Alert */}
      {error && (
        <div className="p-4 rounded-lg bg-rose-950/40 border border-rose-800/60 text-xs text-rose-200 flex items-start gap-3">
          <AlertTriangle className="w-4 h-4 text-rose-400 shrink-0 mt-0.5" />
          <div className="space-y-1">
            <p className="font-semibold">Failed to load empirical experiment records</p>
            <p className="text-rose-300 font-mono text-[11px]">{error}</p>
          </div>
        </div>
      )}

      {/* Main Tab Navigation */}
      <div className="flex items-center gap-2 border-b border-[#22262f] pb-2 overflow-x-auto">
        <button
          onClick={() => setActiveTab('traffic')}
          className={`flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs font-medium transition-all ${
            activeTab === 'traffic'
              ? 'bg-sky-500/15 text-sky-300 border border-sky-500/30'
              : 'text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/40 border border-transparent'
          }`}
        >
          <TrendingUp className="w-4 h-4" />
          <span>Load Stress & Traffic Dynamics</span>
          {loadData?.scenarios && (
            <span className="text-[10px] px-1.5 py-0.2 rounded-full bg-zinc-800 font-mono">
              {loadData.scenarios.length} scenarios
            </span>
          )}
        </button>

        <button
          onClick={() => setActiveTab('retrieval')}
          className={`flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs font-medium transition-all ${
            activeTab === 'retrieval'
              ? 'bg-purple-500/15 text-purple-300 border border-purple-500/30'
              : 'text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/40 border border-transparent'
          }`}
        >
          <BarChart3 className="w-4 h-4" />
          <span>Retrieval Quality & Cost Frontier</span>
          <span className="text-[10px] px-1.5 py-0.2 rounded-full bg-zinc-800 font-mono">
            Stage 6 & 8B.2
          </span>
        </button>

        <button
          onClick={() => setActiveTab('catalog')}
          className={`flex items-center gap-2 px-3.5 py-2 rounded-lg text-xs font-medium transition-all ${
            activeTab === 'catalog'
              ? 'bg-emerald-500/15 text-emerald-300 border border-emerald-500/30'
              : 'text-zinc-400 hover:text-zinc-200 hover:bg-zinc-800/40 border border-transparent'
          }`}
        >
          <Database className="w-4 h-4" />
          <span>Datasets & Pricing Basis</span>
        </button>
      </div>

      {isLoading ? (
        <div className="p-12 text-center space-y-3">
          <RefreshCw className="w-6 h-6 text-sky-400 animate-spin mx-auto" />
          <p className="text-xs text-zinc-400 font-mono">Loading empirical experiment data from disk...</p>
        </div>
      ) : (
        <>
          {/* ========================================================================= */}
          {/* TAB 1: LOAD STRESS & TRAFFIC DYNAMICS */}
          {/* ========================================================================= */}
          {activeTab === 'traffic' && (
            <div className="space-y-6">
              {/* Calibration Fidelity Card */}
              {loadData?.calibration_comparison && (
                <div className="p-4 rounded-xl bg-gradient-to-r from-sky-950/20 via-[#0e121a] to-[#0c0e12] border border-sky-900/40 space-y-3">
                  <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-sky-950/60 pb-2.5">
                    <div className="flex items-center gap-2">
                      <Zap className="w-4 h-4 text-sky-400 shrink-0" />
                      <h3 className="text-xs font-bold text-sky-200 uppercase tracking-wider">
                        Real Groq Baseline vs. Simulator Calibration Fidelity
                      </h3>
                    </div>
                    <Badge variant="blue" size="sm">
                      {loadData.calibration_comparison.difference_pct}% Latency Delta
                    </Badge>
                  </div>

                  <p className="text-xs text-zinc-300 leading-relaxed">
                    {loadData.calibration_comparison.conclusion}
                  </p>

                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 pt-1">
                    <div className="p-3 rounded-lg bg-[#08090d] border border-zinc-800 space-y-1">
                      <div className="text-[10px] font-mono uppercase text-sky-400 font-semibold">
                        Real Groq API (Median)
                      </div>
                      <div className="text-lg font-bold font-mono text-zinc-100">
                        {loadData.calibration_comparison.real_groq_median_ms.toFixed(1)} ms
                      </div>
                      <div className="text-[10px] text-zinc-400">Non-streaming turnaround</div>
                    </div>

                    <div className="p-3 rounded-lg bg-[#08090d] border border-zinc-800 space-y-1">
                      <div className="text-[10px] font-mono uppercase text-purple-400 font-semibold">
                        Simulator (Median)
                      </div>
                      <div className="text-lg font-bold font-mono text-zinc-100">
                        {loadData.calibration_comparison.simulator_median_ms.toFixed(1)} ms
                      </div>
                      <div className="text-[10px] text-zinc-400">Calibrated lognormal</div>
                    </div>

                    <div className="p-3 rounded-lg bg-[#08090d] border border-zinc-800 space-y-1">
                      <div className="text-[10px] font-mono uppercase text-emerald-400 font-semibold">
                        Real Groq TTFT (Median)
                      </div>
                      <div className="text-lg font-bold font-mono text-zinc-100">
                        {loadData.calibration_comparison.real_groq_ttft_median_ms.toFixed(1)} ms
                      </div>
                      <div className="text-[10px] text-zinc-400">Time to first chunk</div>
                    </div>

                    <div className="p-3 rounded-lg bg-[#08090d] border border-zinc-800 space-y-1">
                      <div className="text-[10px] font-mono uppercase text-emerald-400 font-semibold">
                        Simulator TTFT (Median)
                      </div>
                      <div className="text-lg font-bold font-mono text-zinc-100">
                        {loadData.calibration_comparison.simulator_ttft_median_ms.toFixed(1)} ms
                      </div>
                      <div className="text-[10px] text-zinc-400">
                        Delta: {loadData.calibration_comparison.ttft_difference_pct}%
                      </div>
                    </div>
                  </div>
                </div>
              )}

              {/* Traffic Filters Bar */}
              <div className="p-3.5 rounded-lg bg-[#0d0f14] border border-[#1f2229] flex flex-wrap items-center justify-between gap-3 text-xs">
                <div className="flex flex-wrap items-center gap-3">
                  <div className="flex items-center gap-1.5 text-zinc-400 font-mono text-[11px]">
                    <Filter className="w-3.5 h-3.5 text-sky-400" />
                    <span>Source:</span>
                  </div>
                  <div className="flex items-center gap-1 bg-[#08090c] p-0.5 rounded-lg border border-zinc-800">
                    <button
                      onClick={() => setSourceFilter('all')}
                      className={`px-2.5 py-1 rounded text-[11px] font-mono transition-all ${
                        sourceFilter === 'all'
                          ? 'bg-zinc-700 text-zinc-100 font-semibold'
                          : 'text-zinc-400 hover:text-zinc-200'
                      }`}
                    >
                      All ({loadData?.scenarios?.length || 0})
                    </button>
                    <button
                      onClick={() => setSourceFilter('real')}
                      className={`px-2.5 py-1 rounded text-[11px] font-mono transition-all ${
                        sourceFilter === 'real'
                          ? 'bg-sky-600 text-white font-semibold'
                          : 'text-zinc-400 hover:text-zinc-200'
                      }`}
                    >
                      Real Groq (1)
                    </button>
                    <button
                      onClick={() => setSourceFilter('simulator')}
