18:     ? doc.page_numbers 
19:     : (doc.page_number !== null && doc.page_number !== undefined ? [doc.page_number] : []);
20:   const docSec = (doc.section || '').toLowerCase().trim();
21: 
22:   return citations.some((c) => {
