29:       (citPaperId && (docPaperId.includes(citPaperId) || citPaperId.includes(docPaperId) || docArxivId.includes(citPaperId))) ||
30:       (citTitle && docTitle && (docTitle.includes(citTitle) || citTitle.includes(docTitle)));
